    let targets: Vec<_> = super::actors::IMMEDIATE_CAPTURE_TARGETS
        .iter()
        .chain(super::actors::SCHEDULED_RENDER_TARGETS)
        .chain(crate::tween_pose::TARGETS.iter())
        .chain(super::actors::MEDIA_CAPTURE_TARGETS)
        .copied()
        .collect();
    legacy_drain_song_property_subset(lua, &targets)
}

