    tracked: &[mlua::Table],
    function: &mlua::Function,
    beat: f32,
) -> Result<crate::SongLuaFunctionActionCapture, String> {
    let tracked = tracked
        .iter()
        .map(|table| crate::SongLuaTrackedActor {
            table: table.clone(),
            actor: Default::default(),
            target: crate::SongLuaTrackedActorTarget::Player(0),
        })
        .collect::<Vec<_>>();
    crate::lua_util::capture_function_action_blocks(lua, overlays, &tracked, function, beat)
}

