/// Borrowed native output used only by migration comparisons.
pub struct LegacyMessageTarget<'a> {
    pub actor: mlua::Table,
    pub commands: &'a mut Vec<crate::SongLuaOverlayMessageCommand>,
}
fn legacy_message_overlays(
    targets: &[LegacyMessageTarget<'_>],
) -> Vec<crate::lua_util::SongLuaOverlayCompileActor<()>> {
    targets
        .iter()
        .map(|r| crate::lua_util::SongLuaOverlayCompileActor {
            table: r.actor.clone(),
            actor: crate::SongLuaOverlayActor {
                kind: (),
                name: None,
                parent_index: None,
                initial_state: Default::default(),
                message_commands: r.commands.clone(),
            },
            message_sounds: Vec::new(),
        })
        .collect()
}
pub fn legacy_capture_stable_messages(
    lua: &mlua::Lua,
    targets: &mut [LegacyMessageTarget<'_>],
    on_dynamic: impl FnMut(String),
) -> Result<(), String> {
    let mut overlays = legacy_message_overlays(targets);
    let result = crate::lua_util::capture_stable_cross_actor_message_commands(
        lua,
        &mut overlays,
        on_dynamic,
    );
    for (target, overlay) in targets.iter_mut().zip(overlays) {
        *target.commands = overlay.actor.message_commands;
    }
    result
}
pub fn legacy_capture_deferred_messages(
    lua: &mlua::Lua,
    targets: &mut [LegacyMessageTarget<'_>],
    tracked: &mut [LegacyMessageTarget<'_>],
    runtime_captures: &[crate::SongLuaStatefulMessageCapture],
    skipped: &mut Vec<String>,
) -> Result<Vec<(usize, String, std::path::PathBuf)>, String> {
    let mut overlays = legacy_message_overlays(targets);
    let mut tracked_actors = tracked
        .iter()
        .map(|r| crate::SongLuaTrackedActor {
            table: r.actor.clone(),
            actor: crate::SongLuaCapturedActor {
                message_commands: r.commands.clone(),
                ..Default::default()
            },
            target: crate::SongLuaTrackedActorTarget::Player(0),
        })
        .collect::<Vec<_>>();
    let result = crate::lua_util::capture_deferred_messages(
        lua,
        &mut overlays,
        &mut tracked_actors,
        runtime_captures,
        skipped,
    );
    for (target, overlay) in targets.iter_mut().zip(overlays) {
        *target.commands = overlay.actor.message_commands;
    }
    for (target, actor) in tracked.iter_mut().zip(tracked_actors) {
        *target.commands = actor.actor.message_commands;
    }
    result
}

pub fn legacy_capture_overlay_function_eases(
    lua: &mlua::Lua,
    overlays: &[(usize, mlua::Table)],
    function: &mlua::Function,
    params: crate::SongLuaOverlayEaseBuildParams,
    endpoints: [f32; 2],
    probe_actors: &[mlua::Table],
) -> Result<Vec<crate::SongLuaOverlayEase>, String> {
    crate::lua_util::capture_overlay_function_eases(
        lua,
        overlays,
        function,
        params.unit,
        params.start,
        params.limit,
        params.span_mode,
        endpoints[0],
        endpoints[1],
        params.easing,
        params.sustain,
        params.opt1,
        params.opt2,
        &probe_actors
            .iter()
            .map(|a| a.to_pointer() as usize)
            .collect::<Vec<_>>(),
    )
}

pub fn legacy_read_song_overlay_tree<S, V>(
    lua: &mlua::Lua,
    root: mlua::Table,
    context: &crate::SongLuaCompileContext,
    slots: impl Fn(
        &std::path::Path,
        &std::path::Path,
        &std::path::Path,
    ) -> Result<std::sync::Arc<[S]>, String>,
    layer: impl Fn(&S) -> Option<crate::SongLuaOverlayModelLayer<V>>,
    skipped: impl FnMut(String),
) -> Result<LegacySongOverlayActors<S, V>, String> {
    crate::lua_util::read_overlay_compile_actors(
        lua,
        &mlua::Value::Table(root),
        context,
        |actor| crate::lua_util::read_actor_model_layers(actor, &slots, &layer),
        |actor, _| crate::lua_util::read_noteskin_tap_actor_slots(actor, &slots),
        skipped,
    )
}

fn legacy_action_tracked(targets: &[LegacyMessageTarget<'_>]) -> Vec<crate::SongLuaTrackedActor> {
    targets
        .iter()
        .map(|r| crate::SongLuaTrackedActor {
            table: r.actor.clone(),
            actor: crate::SongLuaCapturedActor {
                message_commands: r.commands.clone(),
                ..Default::default()
            },
            target: crate::SongLuaTrackedActorTarget::Player(0),
        })
        .collect()
}
pub fn legacy_compile_function_action(
    lua: &mlua::Lua,
    targets: &mut [LegacyMessageTarget<'_>],
    tracked: &mut [LegacyMessageTarget<'_>],
    function: &mlua::Function,
    beat: f32,
    persists: bool,
    output: &mut super::SongActionOutput<'_>,
) -> Result<bool, String> {
    let mut overlays = legacy_message_overlays(targets);
    let mut tracked_actors = legacy_action_tracked(tracked);
    let result = crate::lua_util::compile_overlay_compile_actor_function_action(
        lua,
        &mut overlays,
        &mut tracked_actors,
        function,
        beat,
        persists,
        output.counter,
        output.messages,
        output.sound_events,
    );
    for (target, row) in targets.iter_mut().zip(overlays) {
        *target.commands = row.actor.message_commands;
    }
    for (target, row) in tracked.iter_mut().zip(tracked_actors) {
        *target.commands = row.actor.message_commands;
    }
    result
}
pub fn legacy_read_overlay_actions(
    lua: &mlua::Lua,
    table: Option<mlua::Table>,
    targets: &mut [LegacyMessageTarget<'_>],
    tracked: &mut [LegacyMessageTarget<'_>],
    output: &mut super::SongActionOutput<'_>,
) -> Result<(), String> {
    let mut overlays = legacy_message_overlays(targets);
    let mut tracked_actors = legacy_action_tracked(tracked);
    let result = crate::lua_util::read_overlay_compile_actor_actions(
        lua,
        table,
        &mut overlays,
        &mut tracked_actors,
        output.messages,
        output.sound_events,
        output.counter,
        output.info,
    );
    for (target, row) in targets.iter_mut().zip(overlays) {
        *target.commands = row.actor.message_commands;
    }
    for (target, row) in tracked.iter_mut().zip(tracked_actors) {
        *target.commands = row.actor.message_commands;
    }
    result
}

