    "#,
    );
    let context = SongLuaCompileContext::new(dir.path(), "progress errors");
    let mut pair = Pair::new(context.clone());
    let (native, rust) = pair.activate(&[&path]);
    let actors = [saved_pair(&mut pair, "actor")];
    test_support::legacy_discover_song_startup_commands(&pair.native, &native, false).unwrap();
    pair.rust
        .discover_song_startup_commands(pair.scene, &rust)
        .unwrap();
    test_support::legacy_begin_song_replay_clock(&pair.native).unwrap();
    test_support::legacy_begin_song_replay(&pair.native, &[], &native).unwrap();
    pair.rust.begin_song_replay(pair.scene, &[], &rust).unwrap();
    pair.rust.set_values(2., 1.).unwrap();
    assert!(test_support::legacy_advance_song_replay(&pair.native, &native, 1., 0.5).is_err());
    assert!(pair.rust.advance_song_replay(pair.scene, 1., 0.5).is_err());
    compare_tween_progress(&mut pair, &actors);
