    ));
    let (native, rust) = pair.activate(&[&path]);
    begin_message_replay(&mut pair, &native, &rust, &["early", "driver", "late"]);
    let frames: Vec<_> = (0..7)
        .map(|i| (i as f64, if i == 0 { 0. } else { 0.125 }))
        .collect();
    test_support::legacy_set_song_replay_frames(&pair.native, &frames).unwrap();
    pair.script("saved.armed=true;saved.early:linear(10):basealpha(0.8)");
    compare_immediate_updates(&mut pair);
    for i in 1..frames.len() {
        let seconds = i as f64 * 0.125;
        pair.rust.set_values(i as f32, seconds as f32).unwrap();
        deadsync_song_lua::set_compile_song_runtime_values(&pair.native, i as f32, seconds as f32)
            .unwrap();
        test_support::legacy_advance_song_replay_at_frame(&pair.native, &native, i, 0.125).unwrap();
        pair.rust
            .advance_song_replay(pair.scene, seconds, 0.125)
            .unwrap();
        pair.compare();
        compare_immediate_updates(&mut pair);
    }
    assert_eq!(pair.compare(), "queue begin|queue end|late|early|driver");
}

fn install_capture_timeline(pair: &Pair, deltas: &[f64]) {
    let frames: Vec<_> = deltas
        .iter()
        .enumerate()
        .map(|(i, &dt)| (i as f64, dt))
        .collect();
    test_support::legacy_set_song_replay_frames(&pair.native, &frames).unwrap();
}

fn advance_capture_frame(
    pair: &mut Pair,
    native: &test_support::LegacySongActivation,
    index: usize,
    seconds: f64,
    delta: f64,
) {
    pair.rust.set_values(index as f32, seconds as f32).unwrap();
    deadsync_song_lua::set_compile_song_runtime_values(&pair.native, index as f32, seconds as f32)
        .unwrap();
    test_support::legacy_advance_song_replay_at_frame(&pair.native, native, index, delta).unwrap();
    pair.rust
        .advance_song_replay(pair.scene, seconds, delta)
        .unwrap();
    pair.compare();
    compare_immediate_updates(pair);
}

