fn install_predicted_frames(pair: &Pair, deltas: &[f64], actor_frames: Option<&[[f32; 2]]>) {
    let frames: Vec<_> = deltas
        .iter()
        .enumerate()
        .map(|(i, dt)| (i as f64, *dt))
        .collect();
    test_support::legacy_set_song_replay_frames(&pair.native, &frames).unwrap();
    test_support::legacy_set_song_replay_actor_frames(&pair.native, actor_frames);
    assert!(
        pair.rust
            .set_song_replay_frames(pair.scene, &frames, actor_frames)
    );
}
fn advance_predicted_frame(
    pair: &mut Pair,
    native: &test_support::LegacySongActivation,
    index: usize,
    seconds: f64,
    delta: f64,
) -> Vec<deadsync_song_lua::rust_engine::SongReplayPropertyUpdates> {
    pair.rust.set_values(index as f32, seconds as f32).unwrap();
    deadsync_song_lua::set_compile_song_runtime_values(&pair.native, index as f32, seconds as f32)
        .unwrap();
