        lua.load("saved.a:playcommand('Hidden');math.random()").exec()?;
        let inner=test_support::legacy_preserving_command_locals(lua,|lua|lua.load("saved.a:playcommand('Hidden');math.randomseed(999);math.random();return tostring(probe_peek())").eval::<String>())?;
        let after=lua.load("saved.a:playcommand('Hidden');return tostring(probe_peek())..','..tostring(math.random())").eval::<String>()?;
        Ok((inner,after))
    }).unwrap();
    let rust=test_support::rust_preserving_command_locals(&mut pair.rust,|runtime| {
        rust_command_script(runtime,"saved.a:playcommand('Hidden');math.random();return ''")?;
        let inner=test_support::rust_preserving_command_locals(runtime,|runtime|rust_command_script(runtime,"saved.a:playcommand('Hidden');math.randomseed(999);math.random();return tostring(probe_peek())"))?;
        let after=rust_command_script(runtime,"saved.a:playcommand('Hidden');return tostring(probe_peek())..','..tostring(math.random())")?;
        Ok((inner,after))
    }).unwrap();
    assert_eq!(rust, native);
    assert_eq!(rust.0, "2");
    assert!(rust.1.starts_with("3,"));
    pair.script("assert(probe_peek()==0);log(math.random())");
}

fn compare_touched_actor_capture(
    pair: &mut Pair,
    selected: &[(usize, &str)],
    arg: Option<f32>,
    beat: Option<f32>,
    error: bool,
    emptied: bool,
) -> Option<deadsync_song_lua::rust_engine::SongActorFunctionBlocks> {
    let mut native = Vec::new();
    let mut rust = Vec::new();
    for &(index, key) in selected {
        let (a, b) = saved_pair(pair, key);
        native.push((index, a));
        rust.push((index, Value::Table(b)));
    }
    let f: mlua::Function = pair.native.globals().get("indexed_probe").unwrap();
    let g = pair.rust.vm_mut().get_global(b"indexed_probe").unwrap();
    let expected =
        test_support::legacy_capture_touched_actor_function(&pair.native, &native, &f, arg, beat);
    let actual = pair
        .rust
        .capture_song_touched_actor_function(&rust, g, arg, beat);
    assert_eq!(
        expected.is_err(),
        error,
        "native capture error: {expected:?}"
    );
    assert_eq!(actual.is_err(), error, "Rust capture error: {actual:?}");
    assert_eq!(
        pair.rust.values().unwrap(),
        deadsync_song_lua::compile_song_runtime_values(&pair.native).unwrap()
    );
    if emptied {
        for ((_, a), (_, b)) in native.iter().zip(&rust) {
            assert!(test_support::legacy_captured_blocks(a).unwrap().is_empty());
            assert!(
                pair.rust
                    .actor_command_capture(*b)
                    .unwrap()
                    .blocks
                    .is_empty()
            );
        }
    }
    pair.compare();
    if error {
        None
    } else {
        let expected = expected.unwrap();
        let actual = actual.unwrap();
        assert_eq!(actual, expected);
        Some(actual)
    }
}

