    assert_eq!(out.info.unsupported_function_actions, 1);
    pair.rust.retire_actor_scene(pair.scene).unwrap();
    drop(pair);
    assert_eq!(out.overlays[0][0].blocks[0].delta.x, Some(12.));
}
